package dev.jarofcucumbers.prscraft;
/** Finite-window weighted inner product. Zero-energy inputs are not a useful orthogonal signalling basis. */
public final class Orthogonality{
    private Orthogonality(){}
    public record Result(double inner,double energyA,double energyB,double normalized,boolean valid,boolean orthogonal,int count,double end){public net.minecraft.nbt.CompoundTag save(){var t=new net.minecraft.nbt.CompoundTag();t.putDouble("inner",inner);t.putDouble("energyA",energyA);t.putDouble("energyB",energyB);t.putDouble("rho",normalized);t.putBoolean("valid",valid);t.putBoolean("orthogonal",orthogonal);t.putInt("count",count);t.putDouble("end",end);return t;}}
    public static Result measure(double[] a,double[] b,double span,OrthogonalitySettings cfg){if(a.length!=b.length||a.length<2||!Double.isFinite(span)||span<=0)throw new IllegalArgumentException("orthogonality");double end=Math.min(span,cfg.end());if(end<=cfg.start())throw new IllegalArgumentException("orthogonality_window");double inner=0,ea=0,eb=0;int count=0;if(cfg.discrete()){int first=(int)Math.ceil(cfg.start()*cfg.sampleHz()),last=(int)Math.ceil(end*cfg.sampleHz());if(last-first>512)throw new IllegalArgumentException("orthogonality_samples");for(int n=first;n<last;n++){double t=n/cfg.sampleHz(),x=sample(a,t/span),y=sample(b,t/span);inner+=x*y;ea+=x*x;eb+=y*y;count++;}}else{double dt=span/a.length;for(int i=0;i<a.length;i++){double left=Math.max(i*dt,cfg.start()),right=Math.min((i+1)*dt,end);if(right<=left)continue;double weight=right-left;inner+=a[i]*b[i]*weight;ea+=a[i]*a[i]*weight;eb+=b[i]*b[i]*weight;count++;}}if(!Double.isFinite(inner)||!Double.isFinite(ea)||!Double.isFinite(eb))throw new IllegalArgumentException("signal_range");boolean valid=ea>1e-20&&eb>1e-20&&count>=2;double rho=valid?Math.max(-1,Math.min(1,inner/Math.sqrt(ea*eb))):0;return new Result(inner,ea,eb,rho,valid,valid&&Math.abs(rho)<=cfg.tolerance(),count,end);}
    private static double sample(double[] values,double fraction){double index=fraction*values.length;int at=Math.max(0,Math.min(values.length-1,(int)index));int next=Math.min(at+1,values.length-1);return values[at]+(values[next]-values[at])*(index-at);}
}
